def _build(slug, desk, h2, para, refkey, items, seed):
    ref_url, ref_label = REFS[refkey]
    li = ''.join(f'<li><b>{items[i]}.</b> {items[i+1]}</li>' for i in range(0, len(items), 2))
    pool = SEE[desk]
    picks = []
    i = seed
    me = '/' + slug + '/'
    while len(picks) < 3:
        u = pool[i % len(pool)]
        i += 1
        if u != me and u not in picks:
            picks.append(u)
    a, b, c = picks
    see = f'<p>See <a href="{a}">{a.strip("/").split("/")[-1].replace("-", " ")}</a>, <a href="{b}">{b.strip("/").split("/")[-1].replace("-", " ")}</a> and <a href="{c}">{c.strip("/").split("/")[-1].replace("-", " ")}</a>.</p>'
    return (f'<h2>{h2}.</h2><p>{para} <a href="{ref_url}" rel="nofollow noopener" target="_blank">{ref_label}</a> publishes material worth reading alongside your own notes.</p>'
            f'<p class="sub8-byline">Reviewed 28 September 2026.</p><ul>{li}</ul>{see}')

