def _top(slug, desk, h2, para1, items, para2, seed):
    ref_url, ref_label = REFS[desk_ref[desk]]
    li = ''.join(f'<li><b>{items[i]}.</b> {items[i+1]}</li>' for i in range(0, len(items), 2))
    pool = SEE[desk]
    picks, i = [], seed
    me = '/' + slug + '/'
    while len(picks) < 3:
        u = pool[i % len(pool)]
        i += 1
        if u != me and u not in picks and u in SEE_LABELS:
            picks.append(u)
    links = ' and '.join([', '.join(f'<a href="{u}">{SEE_LABELS[u]}</a>' for u in picks[:2]), f'<a href="{picks[2]}">{SEE_LABELS[picks[2]]}</a>'])
    p2 = f'<p>{para2}</p>' if para2 else ''
    return (f'<h2>{h2}.</h2><p>{para1} <a href="{ref_url}" rel="nofollow noopener" target="_blank">{ref_label}</a> publishes adjacent material worth reading alongside these notes.</p>'
            f'<ul>{li}</ul>{p2}<p>See {links}.</p>')

